?><!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Riwayat Transaksi</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="../index.php"><span class="brand-icon">BR</span><span><b>Kasir Bu Rina</b><small>Warung & Toko</small></span></a><nav><a href="../index.php">▦ <span>Dashboard</span></a><a href="../produk/index.php">▣ <span>Data Produk</span></a><a href="../transaksi/index.php">＋ <span>Transaksi Kasir</span></a><a class="active" href="index.php">◷ <span>Riwayat Transaksi</span></a></nav></aside><main class="main"><header class="topbar"><div><p class="eyebrow">CATATAN PENJUALAN</p><h1>Riwayat Transaksi</h1></div><a class="btn btn-primary" href="../transaksi/index.php">＋ Transaksi Baru</a></header><section class="panel"><div class="panel-heading"><div><h2>Semua Transaksi</h2><p><?= count($transaksi) ?> transaksi tercatat</p></div></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Tanggal</th><th>Metode</th><th>Total</th><th>Detail</th></tr></thead><tbody><?php if(!$transaksi): ?><tr><td colspan="5" class="empty">Belum ada riwayat transaksi.</td></tr><?php else: foreach($transaksi as $t): ?><tr><td>#<?= $t['id_transaksi'] ?></td><td><?= date('d/m/Y H:i',strtotime($t['tanggal'])) ?></td><td><span class="pill"><?= htmlspecialchars(strtoupper($t['metode_bayar'])) ?></span></td><td class="money"><?= rp($t['total']) ?></td><td><a href="../transaksi/struk.php?id=<?= $t['id_transaksi'] ?>">Lihat struk</a></td></tr><?php endforeach; endif; ?></tbody></table></div></section><footer>© <?= date('Y') ?> Kasir Bu Rina</footer></main></div></body></html>
